    const hazard=hazards[hazardIndex],persistent=['megaRock','megaRockBlock','tribalTotem','totemBlock'].includes(hazard.type);if(!persistent)hazards.splice(hazardIndex,1);flash=1;burst(head.x,head.y,hazard.type==='bambooSpikes'?'#a9783f':'#899084',14);
