  maybeJumpMouse(head);maybeJumpMouse(head,extraMouse);fireSpikeMouse(head);fireSpikeMouse(head,extraMouse);snake.unshift(head);terrainSound(head);
  if(resistanceFruit&&head.x===resistanceFruit.x&&head.y===resistanceFruit.y){bossResistance=true;resistanceFruit=null;mouthUntil=performance.now()+420;burst(head.x,head.y,'#8ee4d7',24);const tail=snake[snake.length-1];if(snake.length<MAX_HEALTH_LENGTH)snake.push({...tail});if(snake.length>MAX_HEALTH_LENGTH)snake.splice(MAX_HEALTH_LENGTH);updateHud()}
  const ateToad=toad&&head.x===toad.x&&head.y===toad.y;if(ateToad){mouthUntil=performance.now()+360;sound('eat');burst(head.x,head.y,'#91b85a',18);mouseHealthBank+=.7;const frogGrowth=mouseHealthBank>=1&&snake.length<=MAX_HEALTH_LENGTH;if(frogGrowth)mouseHealthBank-=1;else snake.pop();if(snake.length>MAX_HEALTH_LENGTH)snake.splice(MAX_HEALTH_LENGTH);toad=null;updateHud()}
  const eaten=head.x===mouse.x&&head.y===mouse.y?mouse:extraMouse&&head.x===extraMouse.x&&head.y===extraMouse.y?extraMouse:null;
  if(eaten&&eaten.type==='boss'&&!bossResistance){eaten.jump=1;eaten.lastJump=performance.now();const escapes=[{x:16,y:5},{x:20,y:5},{x:16,y:8},{x:20,y:8},{x:13,y:6},{x:22,y:6}].filter(p=>!occupied(p.x,p.y));if(escapes.length)Object.assign(eaten,escapes[Math.floor(Math.random()*escapes.length)]);burst(head.x,head.y,'#78c9bd',16);snake.pop();return}
