function drawTemple(){if(level!==5)return;const x=17*CELL,y=4*CELL,w=3*CELL,h=3*CELL;ctx.save();ctx.fillStyle='rgba(8,14,10,.45)';ctx.fillRect(x+10,y+14,w,h+18);ctx.fillStyle='#697268';ctx.strokeStyle='#27332c';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x+8,y+h);ctx.lineTo(x,y+24);ctx.lineTo(x+18,y);ctx.lineTo(x+w-12,y+3);ctx.lineTo(x+w,y+27);ctx.lineTo(x+w-7,y+h);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#929b86';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x+w/2,y+58,25,Math.PI,0);ctx.lineTo(x+w/2+25,y+h);ctx.lineTo(x+w/2-25,y+h);ctx.closePath();ctx.stroke();ctx.fillStyle='#111b15';ctx.fill();ctx.strokeStyle='#3e4b41';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+17,y+20);ctx.lineTo(x+34,y+39);ctx.lineTo(x+22,y+63);ctx.moveTo(x+w-18,y+15);ctx.lineTo(x+w-37,y+38);ctx.lineTo(x+w-24,y+69);ctx.stroke();ctx.fillStyle='#526b48';ctx.beginPath();ctx.arc(x+w/2,y+29,15,0,7);ctx.fill();ctx.fillStyle='#18231b';ctx.beginPath();ctx.arc(x+w/2,y+29,8,0,7);ctx.fill();ctx.restore()}
