function drawDryCacti(){if(level!==4)return;DRY_CACTI.forEach((cactus,index)=>{ctx.save();ctx.translate((cactus.x+.5)*CELL,(cactus.y+.5)*CELL);ctx.scale(cactus.scale,cactus.scale);ctx.shadowColor='rgba(24,18,12,.45)';ctx.shadowBlur=8;ctx.strokeStyle='#263b2b';ctx.lineWidth=2;const pads=cactus.style==='fan'?[[-13,4,10,22,-.55],[0,0,12,28,0],[14,6,10,21,.55],[-22,14,8,15,-.85]]:[[0,2,11,29,0],[-14,8,8,18,-.5],[14,11,8,17,.62]];pads.forEach((p,i)=>{ctx.fillStyle=i%2?'#657b47':'#526b3e';ctx.beginPath();ctx.ellipse(p[0],p[1],p[2],p[3],p[4],0,7);ctx.fill();ctx.stroke();ctx.strokeStyle='#94a469';ctx.lineWidth=1;for(let line=-1;line<=1;line++){ctx.beginPath();ctx.moveTo(p[0]+line*3,p[1]-p[3]*.65);ctx.lineTo(p[0]+line*3,p[1]+p[3]*.65);ctx.stroke()}ctx.fillStyle='#d7c89b';for(let s=0;s<4;s++){const a=s*1.7+i;ctx.beginPath();ctx.moveTo(p[0]+Math.cos(a)*p[2]*.65,p[1]+Math.sin(a)*p[3]*.55);ctx.lineTo(p[0]+Math.cos(a)*p[2]*.65+Math.cos(a)*7,p[1]+Math.sin(a)*p[3]*.55+Math.sin(a)*7);ctx.lineTo(p[0]+Math.cos(a+.35)*p[2]*.55,p[1]+Math.sin(a+.35)*p[3]*.48);ctx.closePath();ctx.fill()}});const fx=index%2?-9:8,fy=-24;ctx.fillStyle=index%2?'#db775e':'#c75d87';for(let p=0;p<6;p++){const a=p*Math.PI/3;ctx.beginPath();ctx.ellipse(fx+Math.cos(a)*6,fy+Math.sin(a)*6,6,3,a,0,7);ctx.fill()}ctx.fillStyle='#edc85f';ctx.beginPath();ctx.arc(fx,fy,3,0,7);ctx.fill();ctx.restore()})}
