function drawBossGuard(){if(!bossGuard||!bossGuard.visible||miceCaught>=10)return;const now=performance.now(),dancing=now>=bossGuard.danceAt,baseX=(bossGuard.x+.5)*CELL,baseY=(bossGuard.y+.5)*CELL,x=baseX+(dancing?Math.sin(now/95)*8:0),y=baseY+(dancing?Math.abs(Math.sin(now/130))*-5:0),tilt=dancing?Math.sin(now/110)*.16:0;ctx.save();ctx.translate(x,y);ctx.rotate(tilt);drawBossFigure(0,0,.95);ctx.restore()}
