function drawLevel5Flora(){if(level!==5)return;const beds=[[28,42,1],[W-31,46,2],[34,H-42,3],[W-36,H-44,4]];beds.forEach(([x,y,seed])=>{for(let i=0;i<13;i++){const a=i*.77+seed*.2,r=15+(i%4)*9,lx=x+Math.cos(a)*r,ly=y+Math.sin(a)*r;ctx.fillStyle=i%3?'#315b3b':'#587847';ctx.beginPath();ctx.ellipse(lx,ly,18,7,a,0,7);ctx.fill()}const color=['#a970cf','#62b7c5','#efbd48','#d6657e'][seed-1];ctx.fillStyle=color;for(let petal=0;petal<6;petal++){const a=petal*Math.PI/3;ctx.beginPath();ctx.ellipse(x+Math.cos(a)*7,y+Math.sin(a)*7,7,3,a,0,7);ctx.fill()}ctx.fillStyle='#d8df89';ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.fill()});const thornBeds=[[8,H*.34,1],[W-8,H*.58,-1],[10,H*.73,1],[W-10,H*.28,-1]];thornBeds.forEach(([x,y,side])=>{ctx.strokeStyle='#273f2c';ctx.lineWidth=5;for(let i=0;i<7;i++){const py=y-35+i*12,len=23+(i%3)*8;ctx.beginPath();ctx.moveTo(x,py);ctx.lineTo(x+side*len,py-8);ctx.stroke();ctx.fillStyle='#66784a';ctx.beginPath();ctx.ellipse(x+side*len,py-8,11,5,-side*.35,0,7);ctx.fill();ctx.fillStyle='#b7c77a';ctx.beginPath();ctx.moveTo(x+side*len*.55,py-4);ctx.lineTo(x+side*(len*.55+9),py-13);ctx.lineTo(x+side*(len*.55+5),py-1);ctx.closePath();ctx.fill()}})}
