function drawToad(){if(!toad)return;const now=performance.now(),x=(toad.x+.5)*CELL,y=(toad.y+.5)*CELL+4,cycle=((now-toad.spawnAt)/1800+toad.flyPhase)%1,flyAngle=now/430+toad.flyPhase,flyX=x+Math.cos(flyAngle)*31,flyY=y-26+Math.sin(flyAngle*1.7)*8,tongue=cycle>.64&&cycle<.82,tongueReach=tongue?Math.sin((cycle-.64)/.18*Math.PI):0;ctx.save();ctx.fillStyle='#326f6b';ctx.strokeStyle='#173f3d';ctx.lineWidth=2.5;ctx.beginPath();ctx.ellipse(x,y+10,32,19,-.06,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='rgba(87,153,141,.72)';ctx.beginPath();ctx.moveTo(x,y+9);for(let i=0;i<9;i++){const a=i*Math.PI*2/9;ctx.lineTo(x+Math.cos(a)*29,y+10+Math.sin(a)*16)}ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(194,229,211,.5)';ctx.lineWidth=1;for(let i=0;i<7;i++){const a=i*Math.PI*2/7;ctx.beginPath();ctx.moveTo(x,y+9);ctx.lineTo(x+Math.cos(a)*28,y+10+Math.sin(a)*15);ctx.stroke()}ctx.fillStyle='#657f3e';ctx.strokeStyle='#253727';ctx.lineWidth=2.2;ctx.beginPath();ctx.ellipse(x,y+2,18,12,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#7f9c4d';ctx.beginPath();ctx.ellipse(x-14,y+8,8,4.5,-.35,0,7);ctx.ellipse(x+14,y+8,8,4.5,.35,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#8fab55';ctx.beginPath();ctx.arc(x-9,y-8,7,0,7);ctx.arc(x+9,y-8,7,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#e7d58a';ctx.beginPath();ctx.arc(x-9,y-10,2.8,0,7);ctx.arc(x+9,y-10,2.8,0,7);ctx.fill();ctx.fillStyle='#132016';ctx.beginPath();ctx.arc(x-9,y-10,1.35,0,7);ctx.arc(x+9,y-10,1.35,0,7);ctx.fill();ctx.strokeStyle='#e88d91';ctx.lineWidth=3;ctx.lineCap='round';if(tongueReach>0){ctx.beginPath();ctx.moveTo(x,y-1);ctx.lineTo(x+(flyX-x)*tongueReach,y-1+(flyY-y+1)*tongueReach);ctx.stroke()}ctx.fillStyle='#151b17';ctx.beginPath();ctx.ellipse(flyX,flyY,2.5,1.7,flyAngle,0,7);ctx.fill();ctx.strokeStyle='rgba(229,239,216,.8)';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(flyX-2,flyY-2,2.5,1,-.5,0,7);ctx.ellipse(flyX+2,flyY-2,2.5,1,.5,0,7);ctx.stroke();ctx.restore()}
