  const x=(mouse.x+.5)*CELL,y=(mouse.y+.5)*CELL,jumper=mouse.type==='jumper',water=mouse.type==='water',spikeMouse=mouse.type==='spike',boss=mouse.type==='boss',body=boss?'#43543a':spikeMouse?'#744f86':water?'#62aaa9':jumper?'#7fa5a2':'#cbbbaa',bob=Math.sin(performance.now()/180)*2-Math.sin(mouse.jump*Math.PI)*(water?10:22);mouse.jump=Math.max(0,mouse.jump-.045);ctx.save();ctx.translate(x,y+bob);if(boss)ctx.scale(1.9,1.9);if(water){ctx.strokeStyle='rgba(111,205,211,.7)';ctx.beginPath();ctx.ellipse(0,12,20,6,0,0,7);ctx.stroke()}if(spikeMouse&&mouse.armed){ctx.fillStyle='#f2e7c9';ctx.strokeStyle='#392c43';for(let i=0;i<9;i++){const a=i*Math.PI*2/9;ctx.save();ctx.rotate(a);ctx.beginPath();ctx.moveTo(2,-3);ctx.lineTo(21,0);ctx.lineTo(2,3);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()}}ctx.fillStyle=body;ctx.beginPath();ctx.ellipse(0,2,jumper||water||spikeMouse||boss?12:11,jumper||water||spikeMouse||boss?9:8,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(8,-3,jumper||water||spikeMouse||boss?6.5:6,0,7);ctx.fill();ctx.fillStyle=boss?'#71805b':spikeMouse?'#c79fce':water?'#e99142':jumper?'#d28b66':'#d99387';ctx.beginPath();ctx.arc(5,-8,jumper||water||spikeMouse||boss?4:3,0,7);ctx.arc(11,-7,jumper||water||spikeMouse||boss?4:3,0,7);ctx.fill();if(jumper){ctx.strokeStyle='#344f54';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-6,-5);ctx.lineTo(-4,8);ctx.moveTo(1,-6);ctx.lineTo(3,9);ctx.stroke()}if(water){ctx.fillStyle='#dbe695';ctx.beginPath();ctx.arc(-2,2,4,0,7);ctx.fill()}if(jumper||water||spikeMouse||boss){ctx.fillStyle=boss?'#2d3828':water?'#e99142':spikeMouse?'#4b3357':'#d7c068';ctx.beginPath();ctx.ellipse(-7,9,7,3.5,-.2,0,7);ctx.ellipse(4,10,6.5,3.2,.18,0,7);ctx.fill()}if(boss){ctx.fillStyle='#78944b';for(let i=0;i<5;i++){ctx.save();ctx.rotate(-.8+i*.35);ctx.beginPath();ctx.ellipse(4,-12,8,3,0,0,7);ctx.fill();ctx.restore()}}ctx.fillStyle='#141a16';ctx.beginPath();ctx.arc(10,-4,1.5,0,7);ctx.fill();ctx.strokeStyle=body;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-9,3);ctx.qua