function drawSpikes(){spikes.forEach(spike=>{const x=(spike.x-spike.dy*spike.lane+.5)*CELL,y=(spike.y+spike.dx*spike.lane+.5)*CELL,a=Math.atan2(spike.dy,spike.dx);ctx.save();ctx.translate(x,y);if(spike.kind==='spit'||spike.kind==='bossSpit'){const pulse=1+Math.sin(performance.now()/70)*.16;ctx.rotate(a);ctx.scale(pulse,pulse);ctx.shadowColor='#8fe84d';ctx.shadowBlur=18;ctx.fillStyle='#071009';ctx.strokeStyle='#79c842';ctx.lineWidth=4;ctx.beginPath();for(let i=0;i<12;i++){const pa=i*Math.PI/6,r=i%2?10:13;ctx.lineTo(Math.cos(pa)*r,Math.sin(pa)*r)}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#a6ef61';ctx.beginPath();ctx.arc(3,-3,3,0,7);ctx.fill();ctx.fillStyle='rgba(75,151,50,.75)';ctx.beginPath();ctx.arc(-17,0,6,0,7);ctx.arc(-27,2,3,0,7);ctx.fill()}else{ctx.rotate(a);ctx.fillStyle='#f2e7c9';ctx.strokeStyle='#4b3357';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(14,0);ctx.lineTo(-10,-5);ctx.lineTo(-6,0);ctx.lineTo(-10,5);ctx.closePath();ctx.fill();ctx.stroke()}ctx.restore()})}
